const p=data.patients.find(x=>x.id===patient)||data.patients[0];const pv=data.visits.filter(x=>x.patient===patient&&!x.draft).sort((a,b)=>a.date.localeCompare(b.date));const last=pv[pv.length-1];const pd=data.docs.filter(x=>x.patient===patient);const pa=data.appointments.filter(x=>x.patient===patient&&x.status==='Programado').sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));const pay=data.payments.filter(x=>x.date.startsWith(month));const collected=pay.reduce((s,x)=>s+x.paid,0),due=pay.reduce((s,x)=>s+x.total-x.paid,0);const name=(id:number)=>data.patients.find(x=>x.id===id)?.name||'Paciente';
