const docList=(list:Doc[])=><div className="doc-list">{list.length?list.map(d=><div className="doc-row premium-doc" key={d.id}><span className={'file-icon '+(d.category==='Laboratorio'?'lab':'')}><FileText size={23}/><b>{d.url?.startsWith('data:image')?'IMG':'PDF'}</b></span><div className="grow"><strong>{d.title}</strong><small>{d.category} · {dateLabel(d.date)} {d.url?'':'· Documento de ejemplo'}</small>{d.notes&&<p>{d.notes}</p>}</div><button className="btn secondary doc-preview" onClick={()=>setDocument(d)}>Vista previa <ArrowUpRight size={16}/></button><button className="iconbtn" aria-label={'Descargar '+d.title} onClick={()=>{if(d.url){const a=window.document.createElement('a');a.href=d.url;a.download=d.title;a.click()}else setDocument(d)}}><Download size={19}/></button></div>):<div className="empty"><span className="empty-art"><Files size={28}/></span><h3>Todo listo para empezar</h3><p>Los documentos que se compartan aparecerán acá, ordenados por fecha.</p></div>}</div>;
