{page==='Pacientes'&&<section className="card"><div className="toolbar"><div className="searchbox"><Search size={18}/><input placeholder="Buscar por nombre, apellido o DNI" value={search} onChange={e=>setSearch(e.target.value)}/></div><select value={filter} onChange={e=>setFilter(e.target.value)}><option>Todos</option><option>Activos</option><option>Suspendidos</option></select><Badge tone="neutral">{data.patients.length} pacientes</Badge></div><div className="table-wrap"><table><thead><tr><th>Paciente</th><th>Objetivo</th><th>Última consulta</th><th>Acceso</th><th/></tr></thead><tbody>{data.patients.filter(x=>(x.name.toLowerCase().includes(search.toLowerCase())||x.dni.includes(search))&&(filter==='Todos'||(filter==='Activos'?x.active:!x.active))).map(x=><tr key={x.id} className="clickable" onClick={()=>openPatient(x.id)}><td><div className="person-cell"><Avatar name={x.name}/><div><strong>{x.name}</strong><small>{x.age} años · {x.os}</small></div></div></td><td>{x.goal}</td><td>{data.visits.some(v=>v.patient===x.id)?dateLabel(data.visits.filter(v=>v.patient===x.id).at(-1)!.date):'Sin consultas'}</td><td><Badge tone={x.active?'green':'neutral'}>{x.active?'Activo':'Suspendido'}</Badge></td><td><ArrowUpRight size={18}/></td></tr>)}</tbody></table></div></section>}
